HaoLangParser::HaoLangParser(TokenStream *input) : HaoLangParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

HaoLangParser::HaoLangParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  HaoLangParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *haolangparserParserStaticData->atn, haolangparserParserStaticData->decisionToDFA, haolangparserParserStaticData->sharedContextCache, options);
}

HaoLangParser::~HaoLangParser() {
  delete _interpreter;
}

const atn::ATN& HaoLangParser::getATN() const {
  return *haolangparserParserStaticData->atn;
}

std::string HaoLangParser::getGrammarFileName() const {
  return "HaoLangParser.g4";
}

const std::vector<std::string>& HaoLangParser::getRuleNames() const {
  return haolangparserParserStaticData->ruleNames;
}

const dfa::Vocabulary& HaoLangParser::getVocabulary() const {
  return haolangparserParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView HaoLangParser::getSerializedATN() const {
  return haolangparserParserStaticData->serializedATN;
}


