HaoLangParser::CompilationUnitContext::CompilationUnitContext(ParserRuleContext *parent, size_t invokingState)
  : ParserRuleContext(parent, invokingState) {
}

tree::TerminalNode* HaoLangParser::CompilationUnitContext::EOF() {
  return getToken(HaoLangParser::EOF, 0);
}

HaoLangParser::PackageDeclContext* HaoLangParser::CompilationUnitContext::packageDecl() {
  return getRuleContext<HaoLangParser::PackageDeclContext>(0);
}

std::vector<HaoLangParser::ImportDeclContext *> HaoLangParser::CompilationUnitContext::importDecl() {
  return getRuleContexts<HaoLangParser::ImportDeclContext>();
}

HaoLangParser::ImportDeclContext* HaoLangParser::CompilationUnitContext::importDecl(size_t i) {
  return getRuleContext<HaoLangParser::ImportDeclContext>(i);
}

std::vector<HaoLangParser::TopLevelDeclContext *> HaoLangParser::CompilationUnitContext::topLevelDecl() {
  return getRuleContexts<HaoLangParser::TopLevelDeclContext>();
}

HaoLangParser::TopLevelDeclContext* HaoLangParser::CompilationUnitContext::topLevelDecl(size_t i) {
  return getRuleContext<HaoLangParser::TopLevelDeclContext>(i);
}


size_t HaoLangParser::CompilationUnitContext::getRuleIndex() const {
  return HaoLangParser::RuleCompilationUnit;
}


std::any HaoLangParser::CompilationUnitContext::accept(tree::ParseTreeVisitor *visitor) {
  if (auto parserVisitor = dynamic_cast<HaoLangParserVisitor*>(visitor))
    return parserVisitor->visitCompilationUnit(this);
  else
    return visitor->visitChildren(this);
}

